#!/usr/bin/env python3
"""
benchmark.py

Multi-API LLM benchmark harness with SSE-based TTFT measurement.

Usage:
    python benchmark.py --config models.json [--output results.json] [--timeout 10] [--workers 4]
"""

import argparse
import concurrent.futures
import datetime
import json
import os
import socket
import sys
import time
import traceback
import uuid
import urllib.error
import urllib.request
from typing import Any, Dict, List, Optional, Tuple

PROMPT = "Reply with exactly one sentence about the color blue."


def iso_now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def load_config(path: str) -> Dict[str, Any]:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict) or "models" not in data or not isinstance(data["models"], list):
        raise ValueError("Config must be a JSON object with a 'models' list.")
    return data


def build_request(model_cfg: Dict[str, Any]) -> Tuple[str, Dict[str, Any]]:
    api_type = model_cfg.get("api_type")
    base_url = model_cfg.get("base_url", "").rstrip("/")
    model_id = model_cfg.get("id")
    temperature = model_cfg.get("temperature")
    max_tokens = model_cfg.get("max_tokens")

    if not base_url:
        raise ValueError("Missing 'base_url'")
    if not model_id:
        raise ValueError("Missing 'id'")
    if api_type not in ("chat_completions", "responses"):
        raise ValueError("api_type must be 'chat_completions' or 'responses'")

    if api_type == "chat_completions":
        url = f"{base_url}/v1/chat/completions"
        body = {
            "model": model_id,
            "messages": [{"role": "user", "content": PROMPT}],
            "stream": True,
        }
        if temperature is not None:
            body["temperature"] = temperature
        if max_tokens is not None:
            body["max_tokens"] = max_tokens
        return url, body

    # responses
    url = f"{base_url}/v1/responses"
    body = {
        "model": model_id,
        "input": PROMPT,
        "stream": True,
    }
    if temperature is not None:
        body["temperature"] = temperature
    if max_tokens is not None:
        body["max_output_tokens"] = max_tokens
    return url, body


def extract_delta_text(api_type: str, payload: Dict[str, Any]) -> str:
    if api_type == "chat_completions":
        choices = payload.get("choices")
        if isinstance(choices, list):
            for choice in choices:
                if not isinstance(choice, dict):
                    continue
                delta = choice.get("delta")
                if isinstance(delta, dict):
                    content = delta.get("content")
                    if isinstance(content, str):
                        return content
        return ""

    # responses API
    if payload.get("type") == "content_block_delta":
        delta = payload.get("delta")
        if isinstance(delta, dict):
            text = delta.get("text")
            if isinstance(text, str):
                return text
    return ""


def benchmark_one(model_cfg: Dict[str, Any], timeout_s: float) -> Dict[str, Any]:
    model_id = model_cfg.get("id")
    api_type = model_cfg.get("api_type")

    result = {
        "model_id": model_id,
        "api_type": api_type,
        "status": "error",
        "ttft_ms": None,
        "total_ms": None,
        "first_token": None,
        "full_response": None,
        "error": None,
    }

    try:
        url, body = build_request(model_cfg)

        api_key_env = model_cfg.get("api_key_env")
        if not api_key_env:
            raise ValueError("Missing 'api_key_env'")
        api_key = os.environ.get(api_key_env)
        if not api_key:
            raise ValueError(f"Environment variable '{api_key_env}' is not set")

        data_bytes = json.dumps(body).encode("utf-8")
        headers = {
            "Content-Type": "application/json",
            "Accept": "text/event-stream",
            "Authorization": f"Bearer {api_key}",
        }

        req = urllib.request.Request(url=url, data=data_bytes, headers=headers, method="POST")

        t_start = time.perf_counter()
        t_first_token = None
        full_parts: List[str] = []
        first_token = None

        with urllib.request.urlopen(req, timeout=timeout_s) as resp:
            # Read SSE stream line-by-line.
            # urllib gives bytes lines; decode as utf-8.
            for raw_line in resp:
                # timeout coverage while streaming:
                if (time.perf_counter() - t_start) > timeout_s:
                    raise TimeoutError(f"Stream timeout after {int(timeout_s * 1000)}ms")

                line = raw_line.decode("utf-8", errors="replace").strip()
                if not line or not line.startswith("data:"):
                    continue

                data_str = line[5:].strip()
                if data_str == "[DONE]":
                    break

                try:
                    payload = json.loads(data_str)
                except json.JSONDecodeError:
                    # skip malformed event but continue
                    continue

                delta_text = extract_delta_text(api_type, payload)
                if delta_text:
                    if t_first_token is None:
                        t_first_token = time.perf_counter()
                        first_token = delta_text
                    full_parts.append(delta_text)

        t_end = time.perf_counter()
        total_ms = (t_end - t_start) * 1000.0
        ttft_ms = (t_first_token - t_start) * 1000.0 if t_first_token is not None else None
        full_response = "".join(full_parts) if full_parts else ""

        result.update(
            {
                "status": "ok",
                "ttft_ms": round(ttft_ms, 3) if ttft_ms is not None else None,
                "total_ms": round(total_ms, 3),
                "first_token": first_token,
                "full_response": full_response,
                "error": None,
            }
        )
        return result

    except urllib.error.HTTPError as e:
        total_ms = None
        try:
            # If request started timing, keep best effort:
            total_ms = round((time.perf_counter() - t_start) * 1000.0, 3)  # type: ignore
        except Exception:
            pass
        msg = f"HTTP {e.code}: {e.reason}"
        try:
            body = e.read().decode("utf-8", errors="replace")
            if body:
                msg += f" | {body[:500]}"
        except Exception:
            pass
        result["error"] = msg
        result["total_ms"] = total_ms
        return result

    except urllib.error.URLError as e:
        total_ms = None
        try:
            total_ms = round((time.perf_counter() - t_start) * 1000.0, 3)  # type: ignore
        except Exception:
            pass
        reason = getattr(e, "reason", e)
        result["error"] = f"Connection error: {reason}"
        result["total_ms"] = total_ms
        return result

    except (socket.timeout, TimeoutError) as e:
        total_ms = None
        try:
            total_ms = round((time.perf_counter() - t_start) * 1000.0, 3)  # type: ignore
        except Exception:
            pass
        result["error"] = str(e) if str(e) else f"Connection timeout after {int(timeout_s * 1000)}ms"
        result["total_ms"] = total_ms
        return result

    except json.JSONDecodeError as e:
        total_ms = None
        try:
            total_ms = round((time.perf_counter() - t_start) * 1000.0, 3)  # type: ignore
        except Exception:
            pass
        result["error"] = f"JSON parse error: {e}"
        result["total_ms"] = total_ms
        return result

    except Exception as e:
        total_ms = None
        try:
            total_ms = round((time.perf_counter() - t_start) * 1000.0, 3)  # type: ignore
        except Exception:
            pass
        result["error"] = f"{type(e).__name__}: {e}"
        result["total_ms"] = total_ms
        return result


def summarize(results: List[Dict[str, Any]]) -> Dict[str, Any]:
    total = len(results)
    ok_results = [r for r in results if r.get("status") == "ok"]
    errors = total - len(ok_results)

    ttft_pairs = []
    for r in ok_results:
        ttft = r.get("ttft_ms")
        if isinstance(ttft, (int, float)):
            ttft_pairs.append((r.get("model_id"), float(ttft)))

    avg_ttft = round(sum(v for _, v in ttft_pairs) / len(ttft_pairs), 3) if ttft_pairs else None
    fastest = min(ttft_pairs, key=lambda x: x[1])[0] if ttft_pairs else None
    slowest = max(ttft_pairs, key=lambda x: x[1])[0] if ttft_pairs else None

    return {
        "total": total,
        "ok": len(ok_results),
        "errors": errors,
        "avg_ttft_ms": avg_ttft,
        "fastest_model": fastest,
        "slowest_model": slowest,
    }


def parse_args(argv: List[str]) -> argparse.Namespace:
    p = argparse.ArgumentParser(description="Benchmark LLM APIs with SSE TTFT measurement.")
    p.add_argument("--config", required=True, help="Path to model config JSON")
    p.add_argument("--output", default="benchmark_results.json", help="Output JSON file")
    p.add_argument("--timeout", type=float, default=30.0, help="Per-model timeout in seconds")
    p.add_argument("--workers", type=int, default=1, help="Parallel workers")
    return p.parse_args(argv)


def main(argv: List[str]) -> int:
    args = parse_args(argv)

    try:
        cfg = load_config(args.config)
    except Exception as e:
        print(f"Failed to load config: {e}", file=sys.stderr)
        return 2

    models = cfg.get("models", [])
    if not models:
        print("No models found in config.", file=sys.stderr)
        return 2

    workers = max(1, int(args.workers))
    timeout_s = float(args.timeout)

    results: List[Dict[str, Any]] = []

    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
        future_map = {
            executor.submit(benchmark_one, model_cfg, timeout_s): model_cfg for model_cfg in models
        }
        for fut in concurrent.futures.as_completed(future_map):
            model_cfg = future_map[fut]
            model_id = model_cfg.get("id", "<unknown>")
            try:
                r = fut.result()
            except Exception as e:
                r = {
                    "model_id": model_id,
                    "api_type": model_cfg.get("api_type"),
                    "status": "error",
                    "ttft_ms": None,
                    "total_ms": None,
                    "first_token": None,
                    "full_response": None,
                    "error": f"Unhandled worker error: {type(e).__name__}: {e}",
                }
            results.append(r)

    # Keep output order same as config order
    order = {m.get("id"): i for i, m in enumerate(models)}
    results.sort(key=lambda r: order.get(r.get("model_id"), 10**9))

    output_obj = {
        "run_id": str(uuid.uuid4()),
        "timestamp": iso_now(),
        "prompt": PROMPT,
        "results": results,
        "summary": summarize(results),
    }

    try:
        with open(args.output, "w", encoding="utf-8") as f:
            json.dump(output_obj, f, indent=2, ensure_ascii=False)
    except Exception as e:
        print(f"Failed to write output file: {e}", file=sys.stderr)
        return 1

    print(f"Wrote benchmark results to {args.output}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
